def _replay_find(pattern, must=''):
    hits = sorted((p for p in glob.glob('/kaggle/input/**/' + pattern, recursive=True) if must in p.lower()), key=len)
    assert hits, f'input not found: {pattern} ({must})'
    return Path(hits[0])


_IN = Path('/kaggle/input')
_real_comp = next(p for p in (_IN / 'competitions/enveda-CASMI26-molecule-id-mass-spectra',
                              _IN / 'enveda-CASMI26-molecule-id-mass-spectra',
                              _IN / 'enveda-casmi26-molecule-id-mass-spectra')
                  if (p / 'train.parquet').is_file())
_mb_path = _replay_find('spectra.parquet', 'massbank')
_ext_dir = _replay_find('ext_meta.parquet', 'extlib').parent

# 1) the query test file, in the schema of the competition's test.parquet
_q = REPLAY['queries'][:REPLAY_N]
_mb = pd.read_parquet(_mb_path)
_by_id = _mb.set_index('spectrum_id')
_rows = []
for _m in _q:
    for _sid, _add, _prec, _ce in _m['spectra']:
        _r = _by_id.loc[_sid]
        _mz = np.asarray(_r.mzs, float); _it = np.asarray(_r.intensities, float)
        _ok = (_mz > 0) & (_it > 0); _o = np.argsort(_mz[_ok]); _mz, _it = _mz[_ok][_o], _it[_ok][_o]
        _ce_s = str(_ce)
        if '%' in _ce_s:
            _v = float(_ce_s.split('%')[0]); _orig, _ev, _units = f'{_v:g}', [round(_v * _prec / 500.0, 1)], 'NCE'
        elif _ce_s.strip() and _ce_s.strip().split()[0].replace('.', '', 1).isdigit():
            _v = float(_ce_s.strip().split()[0]); _orig, _ev, _units = f'{_v:g}', [_v], 'eV'
        else:
            _orig, _ev, _units = None, None, 'unknown'
        _rows.append(dict(molecule_id=_m['molecule_id'], spectrum_id='s_' + hashlib.sha1(_sid.encode()).hexdigest()[:8],
                          ms2_mzs=_mz.tolist(), ms2_normalized_intensities=(_it / _it.max()).tolist(),
                          base_peak_intensity=float(_it.max()), adduct=_add,
                          ionization_mode='positive' if _add.endswith('+') else 'negative',
                          instrument_type=str(_r.instrument_type), precursor_mz=float(_prec),
                          collision_energy_orig=_orig, collision_energy_ev=_ev, collision_energy_orig_units=_units))
_schema = pq.read_schema(_real_comp / 'test.parquet')
pq.write_table(pa.Table.from_pylist(_rows, schema=_schema), REPLAY_COMP / 'test.parquet')
_ids = [m['molecule_id'] for m in _q]
pd.DataFrame(dict(molecule_id=_ids, smiles=';'.join(['CCO'] * 25))).to_csv(REPLAY_COMP / 'sample_submission.csv', index=False)
if not (REPLAY_COMP / 'train.parquet').exists():
    os.symlink(_real_comp / 'train.parquet', REPLAY_COMP / 'train.parquet')
pd.DataFrame([dict(molecule_id=m['molecule_id'], truth_key=m['key'], truth_smiles=m['truth_smiles'], formula=m['formula'],
                   mass=m['mass'], n_spectra=len(m['spectra'])) for m in _q]).to_csv(REPLAY_OUT / 'queries.csv', index=False)

