_mb_dir = REPLAY_LIBS / 'casmi-2026-spectral-library-massbankharmonized'; _mb_dir.mkdir(exist_ok=True)
_mb_keep = _mb[~_mb.spectrum_id.isin(_drop)]
_mb_keep.to_parquet(_mb_dir / 'spectra.parquet', index=False)
_x_dir = REPLAY_LIBS / 'takumuhata-casmi26-extlib'; _x_dir.mkdir(exist_ok=True)
_em = pd.read_parquet(_ext_dir / 'ext_meta.parquet')
_keep = np.ones(len(_em), bool); _keep[REPLAY['extlib_drop_rows']] = False
_em[_keep].reset_index(drop=True).to_parquet(_x_dir / 'ext_meta.parquet', index=False)
for _f in ('ext_mz.npy', 'ext_in.npy'):
    np.save(_x_dir / _f, np.load(_ext_dir / _f, mmap_mode='r')[_keep])
_ems = pd.read_parquet(_ext_dir / 'ext_mass.parquet')
_k2 = np.ones(len(_ems), bool); _k2[REPLAY['ext_mass_drop_rows']] = False
_ems[_k2].reset_index(drop=True).to_parquet(_x_dir / 'ext_mass.parquet', index=False)
_tl = REPLAY_LIBS / 'enveda-casmi26-molecule-id-mass-spectra'; _tl.mkdir(exist_ok=True)
if not (_tl / 'test.parquet').exists():
    os.symlink(REPLAY_COMP / 'test.parquet', _tl / 'test.parquet')

# 3) checks: no query molecule is left in either library by its InChIKey-14, and the pipeline reads the copies
_qik = {m['key'] for m in _q} | {m['raw_ik14'] for m in _q}
assert not set(_mb_keep.inchikey.astype(str).str[:14]) & _qik, 'a query molecule is still in the MassBank copy'
assert not set(_em[_keep].inchikey14.astype(str)) & _qik, 'a query molecule is still in the extlib copy'
assert not set(pq.read_table(_real_comp / 'train.parquet', columns=['inchikey14']).column('inchikey14').to_pylist()) & _qik
if REPLAY_ACTIVE:
    os.environ['CASMI_REPLAY_COMP'] = str(REPLAY_COMP)
    REPLAY_INP = str(REPLAY_LIBS)
else:                                   # setup check: the files are built and checked, nothing reads them
    os.environ.pop('CASMI_REPLAY_COMP', None)
    REPLAY_COMP = _RW / 'replay_comp_inactive'
    REPLAY_INP = '/kaggle/input'
REPLAY_SETUP = dict(active=REPLAY_ACTIVE, molecules=len(_q), spectra=len(_rows), massbank_rows_removed=int(len(_mb) - len(_mb_keep)),
                    extlib_rows_removed=int((~_keep).sum()), ext_mass_rows_removed=int((~_k2).sum()),
                    rdkit_used_for_keys=REPLAY.get('rdkit'))
(REPLAY_OUT / 'setup.json').write_text(json.dumps(REPLAY_SETUP, indent=2))
print('REPLAY SETUP', json.dumps(REPLAY_SETUP))
